mkitem!{mkimpl!{# [extension (pub trait InferCtxtExt <'tcx >)] impl < 'tcx > InferCtxt < 'tcx > { fn can_eq < T : ToTrace < 'tcx > > (& self , param_env : ty :: ParamEnv < 'tcx > , a : T , b : T) -> bool { self . probe (| _ | { let ocx = ObligationCtxt :: new (self) ; let Ok (()) = ocx . eq (& ObligationCause :: dummy () , param_env , a , b) else { return false ; } ; ocx . select_where_possible () . is_empty () }) } fn type_is_copy_modulo_regions (& self , param_env : ty :: ParamEnv < 'tcx > , ty : Ty < 'tcx >) -> bool { let ty = self . resolve_vars_if_possible (ty) ; let copy_def_id = self . tcx . require_lang_item (LangItem :: Copy , DUMMY_SP) ; traits :: type_known_to_meet_bound_modulo_regions (self , param_env , ty , copy_def_id) } fn type_is_clone_modulo_regions (& self , param_env : ty :: ParamEnv < 'tcx > , ty : Ty < 'tcx >) -> bool { let ty = self . resolve_vars_if_possible (ty) ; let clone_def_id = self . tcx . require_lang_item (LangItem :: Clone , DUMMY_SP) ; traits :: type_known_to_meet_bound_modulo_regions (self , param_env , ty , clone_def_id) } fn type_is_use_cloned_modulo_regions (& self , param_env : ty :: ParamEnv < 'tcx > , ty : Ty < 'tcx > ,) -> bool { let ty = self . resolve_vars_if_possible (ty) ; let use_cloned_def_id = self . tcx . require_lang_item (LangItem :: UseCloned , DUMMY_SP) ; traits :: type_known_to_meet_bound_modulo_regions (self , param_env , ty , use_cloned_def_id) } fn type_is_sized_modulo_regions (& self , param_env : ty :: ParamEnv < 'tcx > , ty : Ty < 'tcx >) -> bool { let lang_item = self . tcx . require_lang_item (LangItem :: Sized , DUMMY_SP) ; traits :: type_known_to_meet_bound_modulo_regions (self , param_env , ty , lang_item) } # [doc = " Check whether a `ty` implements given trait(trait_def_id) without side-effects."] # [doc = ""] # [doc = " The inputs are:"] # [doc = ""] # [doc = " - the def-id of the trait"] # [doc = " - the type parameters of the trait, including the self-type"] # [doc = " - the parameter environment"] # [doc = ""] # [doc = " Invokes `evaluate_obligation`, so in the event that evaluating"] # [doc = " `Ty: Trait` causes overflow, EvaluatedToAmbigStackDependent will be returned."] # [doc = ""] # [doc = " `type_implements_trait` is a convenience function for simple cases like"] # [doc = ""] # [doc = " ```ignore (illustrative)"] # [doc = " let copy_trait = infcx.tcx.require_lang_item(LangItem::Copy, span);"] # [doc = " let implements_copy = infcx.type_implements_trait(copy_trait, [ty], param_env)"] # [doc = " .must_apply_modulo_regions();"] # [doc = " ```"] # [doc = ""] # [doc = " In most cases you should instead create an [Obligation] and check whether"] # [doc = "  it holds via [`evaluate_obligation`] or one of its helper functions like"] # [doc = " [`predicate_must_hold_modulo_regions`], because it properly handles higher ranked traits"] # [doc = " and it is more convenient and safer when your `params` are inside a [`Binder`]."] # [doc = ""] # [doc = " [Obligation]: traits::Obligation"] # [doc = " [`evaluate_obligation`]: crate::traits::query::evaluate_obligation::InferCtxtExt::evaluate_obligation"] # [doc = " [`predicate_must_hold_modulo_regions`]: crate::traits::query::evaluate_obligation::InferCtxtExt::predicate_must_hold_modulo_regions"] # [doc = " [`Binder`]: ty::Binder"] # [instrument (level = "debug" , skip (self , params) , ret)] fn type_implements_trait (& self , trait_def_id : DefId , params : impl IntoIterator < Item : Into < GenericArg < 'tcx > > > , param_env : ty :: ParamEnv < 'tcx > ,) -> traits :: EvaluationResult { let trait_ref = ty :: TraitRef :: new (self . tcx , trait_def_id , params) ; let obligation = traits :: Obligation { cause : traits :: ObligationCause :: dummy () , param_env , recursion_depth : 0 , predicate : trait_ref . upcast (self . tcx) , } ; self . evaluate_obligation (& obligation) . unwrap_or (traits :: EvaluationResult :: EvaluatedToErr) } # [doc = " Returns `Some` if a type implements a trait shallowly, without side-effects,"] # [doc = " along with any errors that would have been reported upon further obligation"] # [doc = " processing."] # [doc = ""] # [doc = " - If this returns `Some([])`, then the trait holds modulo regions."] # [doc = " - If this returns `Some([errors..])`, then the trait has an impl for"] # [doc = " the self type, but some nested obligations do not hold."] # [doc = " - If this returns `None`, no implementation that applies could be found."] fn type_implements_trait_shallow (& self , trait_def_id : DefId , ty : Ty < 'tcx > , param_env : ty :: ParamEnv < 'tcx > ,) -> Option < Vec < traits :: FulfillmentError < 'tcx > > > { self . probe (| _snapshot | { let ocx = ObligationCtxt :: new_with_diagnostics (self) ; ocx . register_obligation (Obligation :: new (self . tcx , ObligationCause :: dummy () , param_env , ty :: TraitRef :: new (self . tcx , trait_def_id , [ty]) ,)) ; let errors = ocx . select_where_possible () ; for error in & errors { let Some (trait_clause) = error . obligation . predicate . as_trait_clause () else { continue ; } ; let Some (bound_ty) = trait_clause . self_ty () . no_bound_vars () else { continue } ; if trait_clause . def_id () == trait_def_id && ocx . eq (& ObligationCause :: dummy () , param_env , bound_ty , ty) . is_ok () { return None ; } } Some (errors) }) } }}}
mkitem!{mkimpl!{# [extension (pub trait InferCtxtBuilderExt <'tcx >)] impl < 'tcx > InferCtxtBuilder < 'tcx > { # [doc = " The \"main method\" for a canonicalized trait query. Given the"] # [doc = " canonical key `canonical_key`, this method will create a new"] # [doc = " inference context, instantiate the key, and run your operation"] # [doc = " `op`. The operation should yield up a result (of type `R`) as"] # [doc = " well as a set of trait obligations that must be fully"] # [doc = " satisfied. These obligations will be processed and the"] # [doc = " canonical result created."] # [doc = ""] # [doc = " Returns `NoSolution` in the event of any error."] # [doc = ""] # [doc = " (It might be mildly nicer to implement this on `TyCtxt`, and"] # [doc = " not `InferCtxtBuilder`, but that is a bit tricky right now."] # [doc = " In part because we would need a `for<'tcx>` sort of"] # [doc = " bound for the closure and in part because it is convenient to"] # [doc = " have `'tcx` be free on this function so that we can talk about"] # [doc = " `K: TypeFoldable<TyCtxt<'tcx>>`.)"] fn enter_canonical_trait_query < K , R > (self , canonical_key : & CanonicalQueryInput < 'tcx , K > , operation : impl FnOnce (& ObligationCtxt < '_ , 'tcx > , K) -> Result < R , NoSolution > ,) -> Result < CanonicalQueryResponse < 'tcx , R > , NoSolution > where K : TypeFoldable < TyCtxt < 'tcx > > , R : Debug + TypeFoldable < TyCtxt < 'tcx > > , Canonical < 'tcx , QueryResponse < 'tcx , R > > : ArenaAllocatable < 'tcx > , { let (infcx , key , var_values) = self . build_with_canonical (DUMMY_SP , canonical_key) ; let ocx = ObligationCtxt :: new (& infcx) ; let value = operation (& ocx , key) ? ; ocx . make_canonicalized_query_response (var_values , value) } }}}